{
  "name": "Retail Nexus",
  "description": "A multi-store retail intelligence dashboard featuring AI-driven anomaly detection, revenue tracking, and inventory forecasting in a cyberpunk command center interface.",
  "requestFramePermissions": []
}

{
  "compilerOptions": {
    "target": "ES2022",
    "experimentalDecorators": true,
    "useDefineForClassFields": false,
    "module": "ESNext",
    "lib": [
      "ES2022",
      "DOM",
      "DOM.Iterable"
    ],
    "skipLibCheck": true,
    "types": [
      "node"
    ],
    "moduleResolution": "bundler",
    "isolatedModules": true,
    "moduleDetection": "force",
    "allowJs": true,
    "jsx": "react-jsx",
    "paths": {
      "@/*": [
        "./*"
      ]
    },
    "allowImportingTsExtensions": true,
    "noEmit": true
  }
}

import { Store, Product, Anomaly } from './types';

export const STORES: Store[] = [
  { id: 'S001', name: 'Nexus Prime', region: 'North America', revenueToday: 45200, revenueYesterday: 42100, riskScore: 12, traffic: 1200, conversionRate: 0.24 },
  { id: 'S002', name: 'Neon District', region: 'Asia Pacific', revenueToday: 38900, revenueYesterday: 39500, riskScore: 25, traffic: 980, conversionRate: 0.21 },
  { id: 'S003', name: 'Cyber Port', region: 'Europe', revenueToday: 28500, revenueYesterday: 31000, riskScore: 65, traffic: 750, conversionRate: 0.18 },
  { id: 'S004', name: 'Grid Node 7', region: 'North America', revenueToday: 52100, revenueYesterday: 48000, riskScore: 5, traffic: 1400, conversionRate: 0.28 },
  { id: 'S005', name: 'Sector 9', region: 'Europe', revenueToday: 12400, revenueYesterday: 18000, riskScore: 88, traffic: 400, conversionRate: 0.15 },
];

export const PRODUCTS: Product[] = [
  { id: 'P001', name: 'Quantum Processor', category: 'Electronics', price: 499, stock: 45, salesRate: 5, restockDate: '2024-06-01' },
  { id: 'P002', name: 'Neural Interface', category: 'Wearables', price: 1299, stock: 12, salesRate: 2, restockDate: '2024-05-28' },
  { id: 'P003', name: 'Holo-Projector', category: 'Electronics', price: 250, stock: 150, salesRate: 15, restockDate: '2024-06-10' },
  { id: 'P004', name: 'Cyber Deck', category: 'Computing', price: 899, stock: 8, salesRate: 1, restockDate: '2024-05-25' },
  { id: 'P005', name: 'Stealth Jacket', category: 'Apparel', price: 199, stock: 300, salesRate: 20, restockDate: '2024-06-15' },
];

export const INITIAL_ANOMALIES: Anomaly[] = [
  { id: 'A1', severity: 'high', title: 'Revenue Drop Alert', description: 'Store S005 (Sector 9) revenue dropped 31% compared to 7-day average.', timestamp: '10:42 AM', storeId: 'S005' },
  { id: 'A2', severity: 'medium', title: 'Stockout Warning', description: 'Product P002 (Neural Interface) predicted to stock out in 48 hours across 3 regions.', timestamp: '09:15 AM' },
];

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Store {
  id: string;
  name: string;
  region: string;
  revenueToday: number;
  revenueYesterday: number;
  riskScore: number; // 0-100
  traffic: number;
  conversionRate: number;
}

export interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
  stock: number;
  salesRate: number; // units per day
  restockDate: string;
}

export interface Sale {
  date: string;
  amount: number;
  storeId: string;
  category: string;
}

export interface Anomaly {
  id: string;
  severity: 'high' | 'medium' | 'low';
  title: string;
  description: string;
  storeId?: string;
  timestamp: string;
}

export interface DashboardMetrics {
  totalRevenue: number;
  totalTraffic: number;
  avgConversion: number;
  activeStores: number;
}

export enum ViewState {
  DASHBOARD = 'DASHBOARD',
  STORES = 'STORES',
  INVENTORY = 'INVENTORY',
  AI_INSIGHTS = 'AI_INSIGHTS',
}

import path from 'path';
import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig(({ mode }) => {
    const env = loadEnv(mode, '.', '');
    return {
      server: {
        port: 3000,
        host: '0.0.0.0',
      },
      plugins: [react()],
      define: {
        'process.env.API_KEY': JSON.stringify(env.GEMINI_API_KEY),
        'process.env.GEMINI_API_KEY': JSON.stringify(env.GEMINI_API_KEY)
      },
      resolve: {
        alias: {
          '@': path.resolve(__dirname, '.'),
        }
      }
    };
});

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { Dashboard } from './components/Dashboard';
import { Inventory } from './components/Inventory';
import { AIInsights } from './components/AIInsights';
import { STORES, PRODUCTS, INITIAL_ANOMALIES } from './constants';
import { ViewState, Store } from './types';
import { Search, Bell, User } from 'lucide-react';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.DASHBOARD);
  const [stores, setStores] = useState<Store[]>(STORES);
  // In a real app, we would fetch this data

  return (
    <div className="min-h-screen bg-bg text-text font-sans selection:bg-neon selection:text-black overflow-x-hidden">
      <Sidebar currentView={view} onChangeView={setView} />

      <main className="lg:ml-64 min-h-screen flex flex-col">
        {/* Top Header */}
        <header className="h-16 border-b border-grid bg-bg/90 backdrop-blur-md sticky top-0 z-40 px-6 flex items-center justify-between">
          <div className="flex items-center flex-1">
             <div className="relative w-64 hidden md:block">
               <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500" />
               <input 
                 type="text" 
                 placeholder="Search stores, products..." 
                 className="w-full bg-card border border-grid rounded-sm py-1.5 pl-9 pr-4 text-sm text-white focus:outline-none focus:border-neon placeholder:text-gray-600"
               />
             </div>
          </div>

          <div className="flex items-center gap-4">
             <button className="relative p-2 text-gray-400 hover:text-white transition-colors">
                <Bell className="w-5 h-5" />
                <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-neon rounded-full shadow-neon animate-pulse"></span>
             </button>
             <div className="h-6 w-px bg-grid"></div>
             <div className="flex items-center gap-3">
               <div className="text-right hidden sm:block">
                 <div className="text-sm font-bold text-white">Admin</div>
                 <div className="text-xs text-muted">HQ Command</div>
               </div>
               <div className="w-8 h-8 bg-grid rounded-full flex items-center justify-center border border-gray-700">
                 <User className="w-4 h-4 text-gray-300" />
               </div>
             </div>
          </div>
        </header>

        {/* View Content */}
        <div className="p-6 flex-1 relative">

          {/* View Title */}
          <div className="mb-8 flex justify-between items-end">
             <div>
                <h1 className="text-3xl font-display font-bold text-white uppercase tracking-tight">
                  {view === ViewState.DASHBOARD && 'Global Overwatch'}
                  {view === ViewState.STORES && 'Store Intelligence'}
                  {view === ViewState.INVENTORY && 'Supply Chain Matrix'}
                  {view === ViewState.AI_INSIGHTS && 'Neural Core Analysis'}
                </h1>
                <p className="text-muted mt-1 text-sm font-mono">
                  SYSTEM_TIME: {new Date().toLocaleTimeString()} // STATUS: ONLINE
                </p>
             </div>
             {view === ViewState.DASHBOARD && (
                <div className="hidden md:flex gap-2">
                   <button className="px-3 py-1.5 bg-card border border-grid text-xs font-mono text-white hover:border-neon transition-colors rounded-sm">24H</button>
                   <button className="px-3 py-1.5 bg-transparent border border-grid text-xs font-mono text-muted hover:text-white transition-colors rounded-sm">7D</button>
                   <button className="px-3 py-1.5 bg-transparent border border-grid text-xs font-mono text-muted hover:text-white transition-colors rounded-sm">30D</button>
                </div>
             )}
          </div>

          {view === ViewState.DASHBOARD && <Dashboard stores={stores} viewMode="overview" />}
          {view === ViewState.STORES && <Dashboard stores={stores} viewMode="stores" />}
          {view === ViewState.INVENTORY && <Inventory products={PRODUCTS} />}
          {view === ViewState.AI_INSIGHTS && <AIInsights stores={stores} products={PRODUCTS} initialAnomalies={INITIAL_ANOMALIES} />}

        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area, Treemap } from 'recharts';
import { Store, Sale } from '../types';
import { MetricCard } from './ui/MetricCard';
import { MapPin, AlertTriangle, TrendingUp, Users, Activity } from 'lucide-react';

interface DashboardProps {
  stores: Store[];
  viewMode?: 'overview' | 'stores';
}

// Mock data for charts
const HOURLY_TRAFFIC = [
  { time: '08:00', traffic: 120 },
  { time: '10:00', traffic: 340 },
  { time: '12:00', traffic: 600 },
  { time: '14:00', traffic: 520 },
  { time: '16:00', traffic: 480 },
  { time: '18:00', traffic: 750 },
  { time: '20:00', traffic: 300 },
];

const REGION_DATA = [
  { name: 'North America', size: 97300, fill: '#2CB9FF' },
  { name: 'Europe', size: 40900, fill: '#7D5CFF' },
  { name: 'Asia Pacific', size: 38900, fill: '#32D74B' },
];

export const Dashboard: React.FC<DashboardProps> = ({ stores, viewMode = 'overview' }) => {
  const totalRevenue = stores.reduce((acc, s) => acc + s.revenueToday, 0);
  const totalYesterday = stores.reduce((acc, s) => acc + s.revenueYesterday, 0);
  const revenueTrend = ((totalRevenue - totalYesterday) / totalYesterday) * 100;

  const totalTraffic = stores.reduce((acc, s) => acc + s.traffic, 0);
  const avgConversion = (stores.reduce((acc, s) => acc + s.conversionRate, 0) / stores.length) * 100;

  const sortedStores = [...stores].sort((a, b) => b.revenueToday - a.revenueToday);

  // Custom Tooltip for Treemap
  const CustomTreemapContent = (props: any) => {
    const { root, depth, x, y, width, height, index, payload, name, value } = props;

    // Safe access for payload.fill to prevent crashes
    const fillColor = (payload && payload.fill) ? payload.fill : '#1F2330';

    return (
      <g>
        <rect
          x={x}
          y={y}
          width={width}
          height={height}
          style={{
            fill: fillColor,
            stroke: '#090A0F',
            strokeWidth: 2,
            strokeOpacity: 1,
          }}
        />
        {width > 50 && height > 30 && (
          <text
            x={x + width / 2}
            y={y + height / 2}
            textAnchor="middle"
            fill="#fff"
            fontSize={12}
            fontWeight="bold"
            fontFamily="Space Grotesk"
          >
            {name}
          </text>
        )}
        {width > 50 && height > 50 && (
           <text
            x={x + width / 2}
            y={y + height / 2 + 16}
            textAnchor="middle"
            fill="#fff"
            fontSize={10}
            fontFamily="IBM Plex Mono"
            opacity={0.8}
           >
             ${(value / 1000).toFixed(1)}k
           </text>
        )}
      </g>
    );
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <MetricCard 
          title="Total Revenue" 
          value={`$${totalRevenue.toLocaleString()}`} 
          trend={Number(revenueTrend.toFixed(1))}
          icon={<TrendingUp className="w-5 h-5 text-neon" />}
        />
        <MetricCard 
          title="Total Traffic" 
          value={totalTraffic.toLocaleString()} 
          trend={5.2}
          color="purple"
          icon={<Users className="w-5 h-5 text-purple" />}
        />
        <MetricCard 
          title="Avg Conversion" 
          value={`${avgConversion.toFixed(1)}%`} 
          trend={-1.2}
          color="default"
          icon={<Activity className="w-5 h-5 text-white" />}
        />
        <MetricCard 
          title="Active Stores" 
          value={stores.length.toString()} 
          trendLabel="All systems operational"
          color="neon"
          icon={<MapPin className="w-5 h-5 text-neon" />}
        />
      </div>

      {viewMode === 'overview' ? (
        <>
          {/* Main Visuals */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

            {/* Store Leaderboard */}
            <div className="lg:col-span-2 bg-card border border-grid rounded-sm p-6">
              <h3 className="text-lg font-display font-bold text-white mb-6 flex items-center">
                <span className="w-2 h-6 bg-neon mr-3"></span>
                Store Leaderboard (Today)
              </h3>
              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm">
                  <thead>
                    <tr className="border-b border-grid text-muted font-mono">
                      <th className="pb-3 pl-2">Rank</th>
                      <th className="pb-3">Store Name</th>
                      <th className="pb-3">Region</th>
                      <th className="pb-3 text-right">Risk Score</th>
                      <th className="pb-3 text-right">Revenue</th>
                    </tr>
                  </thead>
                  <tbody>
                    {sortedStores.map((store, index) => (
                      <tr key={store.id} className="border-b border-grid/50 hover:bg-grid/30 transition-colors group">
                        <td className="py-4 pl-2 font-mono text-muted group-hover:text-white">0{index + 1}</td>
                        <td className="py-4 font-medium text-white">{store.name}</td>
                        <td className="py-4 text-gray-400">{store.region}</td>
                        <td className="py-4 text-right">
                          <span className={`
                            px-2 py-1 rounded-sm text-xs font-bold font-mono
                            ${store.riskScore > 70 ? 'bg-danger/20 text-danger border border-danger/50' : 
                              store.riskScore > 30 ? 'bg-warning/20 text-warning border border-warning/50' : 
                              'bg-success/20 text-success border border-success/50'}
                          `}>
                            {store.riskScore}
                          </span>
                        </td>
                        <td className="py-4 text-right font-mono text-neon">
                          ${store.revenueToday.toLocaleString()}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Regional Heatmap Visual */}
            <div className="bg-card border border-grid rounded-sm p-6 flex flex-col">
              <h3 className="text-lg font-display font-bold text-white mb-6 flex items-center">
                <span className="w-2 h-6 bg-purple mr-3"></span>
                Regional Intensity
              </h3>
              <div className="flex-1 min-h-[300px]">
                <ResponsiveContainer width="100%" height="100%">
                    <Treemap
                      data={REGION_DATA}
                      dataKey="size"
                      aspectRatio={4 / 3}
                      stroke="#090A0F"
                      content={<CustomTreemapContent />}
                    />
                  </ResponsiveContainer>
              </div>
            </div>
          </div>

          {/* Hourly Traffic Trend */}
          <div className="bg-card border border-grid rounded-sm p-6">
            <h3 className="text-lg font-display font-bold text-white mb-6">Network-Wide Hourly Traffic</h3>
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={HOURLY_TRAFFIC}>
                  <defs>
                    <linearGradient id="colorTraffic" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#2CB9FF" stopOpacity={0.3}/>
                      <stop offset="95%" stopColor="#2CB9FF" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="#1F2330" vertical={false} />
                  <XAxis dataKey="time" stroke="#94A3B8" fontSize={12} tickLine={false} axisLine={false} />
                  <YAxis stroke="#94A3B8" fontSize={12} tickLine={false} axisLine={false} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#11131A', borderColor: '#1F2330', color: '#fff' }}
                    itemStyle={{ color: '#2CB9FF' }}
                  />
                  <Area type="monotone" dataKey="traffic" stroke="#2CB9FF" strokeWidth={3} fillOpacity={1} fill="url(#colorTraffic)" />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
        </>
      ) : (
        /* Detailed Stores View */
        <div className="bg-card border border-grid rounded-sm p-6 animate-fade-in">
          <h3 className="text-lg font-display font-bold text-white mb-6 flex items-center">
            <span className="w-2 h-6 bg-neon mr-3"></span>
            Store Network Performance
          </h3>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead>
                <tr className="border-b border-grid text-muted font-mono">
                  <th className="pb-3 pl-2">Rank</th>
                  <th className="pb-3">Store Name</th>
                  <th className="pb-3">Region</th>
                  <th className="pb-3 text-right">Traffic</th>
                  <th className="pb-3 text-right">Conversion</th>
                  <th className="pb-3 text-right">Risk Score</th>
                  <th className="pb-3 text-right">Revenue (Today)</th>
                  <th className="pb-3 text-right">Status</th>
                </tr>
              </thead>
              <tbody>
                {sortedStores.map((store, index) => (
                  <tr key={store.id} className="border-b border-grid/50 hover:bg-grid/30 transition-colors group">
                    <td className="py-4 pl-2 font-mono text-muted group-hover:text-white">0{index + 1}</td>
                    <td className="py-4 font-medium text-white">
                      <div className="flex flex-col">
                        <span className="text-base">{store.name}</span>
                        <span className="text-xs text-muted">{store.id}</span>
                      </div>
                    </td>
                    <td className="py-4 text-gray-400">{store.region}</td>
                    <td className="py-4 text-right font-mono text-white">{store.traffic.toLocaleString()}</td>
                    <td className="py-4 text-right font-mono text-white">{(store.conversionRate * 100).toFixed(1)}%</td>
                    <td className="py-4 text-right">
                      <span className={`
                        px-2 py-1 rounded-sm text-xs font-bold font-mono
                        ${store.riskScore > 70 ? 'bg-danger/20 text-danger border border-danger/50' : 
                          store.riskScore > 30 ? 'bg-warning/20 text-warning border border-warning/50' : 
                          'bg-success/20 text-success border border-success/50'}
                      `}>
                        {store.riskScore}
                      </span>
                    </td>
                    <td className="py-4 text-right font-mono text-neon text-lg">
                      ${store.revenueToday.toLocaleString()}
                    </td>
                    <td className="py-4 text-right">
                       <div className="flex items-center justify-end gap-2">
                         <div className={`w-2 h-2 rounded-full ${store.riskScore > 50 ? 'bg-danger animate-pulse' : 'bg-success'}`} />
                         <span className="text-xs uppercase text-muted">{store.riskScore > 50 ? 'At Risk' : 'Stable'}</span>
                       </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Anomaly, Store, Product } from '../types';
import { analyzeRetailData, AIAnalysisResult } from '../services/geminiService';
import { AlertTriangle, Sparkles, RefreshCw, CheckCircle, TrendingDown } from 'lucide-react';

interface AIInsightsProps {
  stores: Store[];
  products: Product[];
  initialAnomalies: Anomaly[];
}

export const AIInsights: React.FC<AIInsightsProps> = ({ stores, products, initialAnomalies }) => {
  const [anomalies, setAnomalies] = useState<Anomaly[]>(initialAnomalies);
  const [analysis, setAnalysis] = useState<AIAnalysisResult | null>(null);
  const [loading, setLoading] = useState(false);

  const handleRunAnalysis = async () => {
    setLoading(true);
    try {
      const result = await analyzeRetailData(stores, products);
      setAnalysis(result);

      // Merge new anomalies
      const newAnomalies = result.anomalies.map((a, i) => ({
        id: `AI-${Date.now()}-${i}`,
        title: a.title,
        description: a.description,
        severity: a.severity,
        storeId: a.relatedStoreId,
        timestamp: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})
      }));

      setAnomalies(newAnomalies);
    } catch (e) {
      console.error("Analysis failed", e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6 animate-fade-in">

      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-display font-bold text-white flex items-center gap-2">
            <BrainCircuitIcon className="text-purple" />
            Nexus AI Intelligence
          </h2>
          <p className="text-muted mt-1">Real-time anomaly detection and strategic forecasting.</p>
        </div>
        <button 
          onClick={handleRunAnalysis}
          disabled={loading}
          className={`
            flex items-center px-6 py-3 rounded-sm font-bold font-mono tracking-wider transition-all
            ${loading 
              ? 'bg-grid cursor-wait text-muted' 
              : 'bg-purple hover:bg-purple-dark text-white shadow-purple hover:shadow-lg hover:-translate-y-0.5'}
          `}
        >
          {loading ? (
            <>
              <RefreshCw className="w-5 h-5 mr-2 animate-spin" />
              PROCESSING DATA...
            </>
          ) : (
            <>
              <Sparkles className="w-5 h-5 mr-2" />
              RUN DEEP SCAN
            </>
          )}
        </button>
      </div>

      {/* Executive Summary Section */}
      {analysis && (
        <div className="bg-card border border-purple/30 rounded-sm p-8 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-purple/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/3 pointer-events-none"></div>

          <h3 className="text-lg font-display font-bold text-purple mb-4">EXECUTIVE SUMMARY</h3>
          <p className="text-lg text-white leading-relaxed max-w-4xl mb-8 font-light border-l-2 border-purple pl-4">
            {analysis.summary}
          </p>

          <div className="bg-black/30 p-6 rounded-sm border border-purple/20">
            <h4 className="text-sm font-mono text-purple mb-2 uppercase">Strategic Recommendation</h4>
            <p className="text-white italic">"{analysis.strategicAdvice}"</p>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Anomaly Feed */}
        <div className="lg:col-span-2 space-y-4">
          <h3 className="text-lg font-display font-bold text-white mb-2">Detected Anomalies</h3>

          {anomalies.length === 0 ? (
             <div className="p-12 text-center border border-grid border-dashed rounded-sm text-muted">
               <CheckCircle className="w-12 h-12 mx-auto mb-4 text-grid" />
               <p>System nominal. No anomalies detected.</p>
             </div>
          ) : (
            anomalies.map((anomaly) => (
              <div 
                key={anomaly.id} 
                className={`
                  relative pl-6 pr-6 py-5 bg-card border rounded-sm shadow-lg flex items-start gap-4 transition-all hover:bg-[#161922]
                  ${anomaly.severity === 'high' ? 'border-l-4 border-l-danger border-y-grid border-r-grid' : 
                    anomaly.severity === 'medium' ? 'border-l-4 border-l-warning border-y-grid border-r-grid' : 
                    'border-l-4 border-l-neon border-y-grid border-r-grid'}
