import { GoogleGenAI, Type } from "@google/genai";
import { Store, Product } from "../types";

// Define the interface for the structured response we want from Gemini
export interface AIAnalysisResult {
  summary: string;
  anomalies: Array<{
    title: string;
    description: string;
    severity: 'high' | 'medium' | 'low';
    relatedStoreId?: string;
  }>;
  strategicAdvice: string;
}

export const analyzeRetailData = async (stores: Store[], products: Product[]): Promise<AIAnalysisResult> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      throw new Error("API Key not found");
    }

    const ai = new GoogleGenAI({ apiKey });

    const prompt = `
      Analyze the following retail chain data. 
      Provide a brief executive summary, identify key anomalies (performance drops, stock risks, high performers), and offer one strategic piece of advice.

      Stores Data: ${JSON.stringify(stores)}
      Products Data: ${JSON.stringify(products)}

      Return the response in strict JSON format.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            anomalies: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  description: { type: Type.STRING },
                  severity: { type: Type.STRING, enum: ["high", "medium", "low"] },
                  relatedStoreId: { type: Type.STRING, nullable: true },
                }
              }
            },
            strategicAdvice: { type: Type.STRING },
          }
        }
      }
    });

    if (response.text) {
        return JSON.parse(response.text) as AIAnalysisResult;
    }
    throw new Error("Empty response from AI");

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return {
      summary: "AI Analysis unavailable at this moment. Please check API configuration.",
      anomalies: [],
      strategicAdvice: "Monitor manual dashboards for critical changes."
    };
  }
};

export const chatWithData = async (query: string, contextData: string) => {
  try {
     const apiKey = process.env.API_KEY;
    if (!apiKey) throw new Error("No API Key");
    const ai = new GoogleGenAI({ apiKey });

    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: `Context: ${contextData}\n\nUser Query: ${query}\n\nAnswer as a Retail Intelligence AI. Keep it brief and metric-focused.`,
    });
    return response.text;
  } catch (e) {
      console.error(e);
      return "System offline. Unable to process query.";
  }
}

import React from 'react';
import { Product } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';

interface InventoryProps {
  products: Product[];
}

export const Inventory: React.FC<InventoryProps> = ({ products }) => {
  // Calculate stockout days
  const data = products.map(p => ({
    name: p.name,
    stock: p.stock,
    daysLeft: Math.round(p.stock / p.salesRate),
    category: p.category
  })).sort((a, b) => a.daysLeft - b.daysLeft);

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Stockout Prediction Chart */}
        <div className="bg-card border border-grid rounded-sm p-6">
          <h3 className="text-lg font-display font-bold text-white mb-6">Stockout Forecast (Days Remaining)</h3>
          <div className="h-[400px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={data} layout="vertical" margin={{ left: 40 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1F2330" horizontal={false} />
                <XAxis type="number" stroke="#94A3B8" />
                <YAxis dataKey="name" type="category" width={120} stroke="#94A3B8" fontSize={11} />
                <Tooltip 
                  cursor={{fill: '#1F2330'}}
                  contentStyle={{ backgroundColor: '#11131A', borderColor: '#1F2330', color: '#fff' }}
                />
                <Legend />
                <Bar dataKey="daysLeft" fill="#2CB9FF" name="Days until empty" radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Product Table */}
        <div className="bg-card border border-grid rounded-sm p-6 flex flex-col">
          <h3 className="text-lg font-display font-bold text-white mb-6">Product Velocity</h3>
          <div className="overflow-x-auto flex-1">
            <table className="w-full text-left text-sm">
              <thead className="border-b border-grid text-muted font-mono">
                <tr>
                  <th className="pb-3">Product</th>
                  <th className="pb-3 text-right">Stock</th>
                  <th className="pb-3 text-right">Daily Sales</th>
                  <th className="pb-3 text-right">Status</th>
                </tr>
              </thead>
              <tbody>
                {products.map((p) => {
                   const daysLeft = Math.round(p.stock / p.salesRate);
                   let statusColor = 'text-success';
                   let statusText = 'Healthy';
                   if (daysLeft < 5) {
                       statusColor = 'text-danger';
                       statusText = 'Critical';
                   } else if (daysLeft < 14) {
                       statusColor = 'text-warning';
                       statusText = 'Low';
                   }

                   return (
                    <tr key={p.id} className="border-b border-grid/50 hover:bg-grid/30 transition-colors">
                        <td className="py-4 font-medium text-white">
                            <div className="flex flex-col">
                                <span>{p.name}</span>
                                <span className="text-xs text-muted">{p.category}</span>
                            </div>
                        </td>
                        <td className="py-4 text-right font-mono text-white">{p.stock}</td>
                        <td className="py-4 text-right font-mono text-white">{p.salesRate}</td>
                        <td className="py-4 text-right">
                            <span className={`font-mono text-xs uppercase font-bold ${statusColor}`}>
                                {statusText}
                            </span>
                        </td>
                    </tr>
                   );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

